SELECT id, title, detail, category, priority, due_date, completed, deleted_at, created_at, updated_at
FROM todos

    deleted_at IS NULL

        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND due_date IS NOT NULL AND due_date >= #{from}


        AND due_date IS NOT NULL AND due_date <= #{to}


ORDER BY due_date

    DESC
    ASC

SELECT id, title, detail, category, priority, due_date, completed, deleted_at, created_at, updated_at
FROM todos


LIMIT #{limit} OFFSET #{offset}

